package com.lqq.supportflow.action.application;
import com.lqq.supportflow.action.domain.*; import java.util.List; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class ManageApprovalService { private final ApprovalPort approvals; public ManageApprovalService(ApprovalPort approvals){this.approvals=approvals;} @Transactional public Approval create(Long tenantId,Long customerId,String actionType,String actionSummary,Long membershipId){return approvals.create(tenantId,customerId,actionType,actionSummary,membershipId);} public List<Approval> list(Long tenantId){return approvals.list(tenantId);} @Transactional public Approval decide(Long tenantId,Long approvalId,Long membershipId,ApprovalStatus decision,String idempotencyKey){return approvals.decide(tenantId,approvalId,membershipId,decision,idempotencyKey);}}
